"""بیوگرافی‌های کوتاه و تصادفی، با history مستقل هر گروه."""
import random

BIOGRAPHIES = [
"کم‌حرفم، ولی بی‌حرف نیستم.","آرومم؛ نه بی‌حس.","دارم نسخه بهتر خودمو آپدیت می‌کنم.","نه دنبال تاییدم، نه دنبال حاشیه.","شب‌ها بیشتر خودمم.","ساده می‌گیرم، عمیق فکر می‌کنم.","حالم خوبه، فقط زیاد توضیحش نمی‌دم.","یه آدم معمولی با فکرهای غیرمعمولی.","از سکوت‌های طولانی نمی‌ترسم.","کم پیدا، ولی واقعی.","با هر کسی صمیمی نمی‌شم.","یه قدم عقب، صد قدم فکر.","مودم با موزیک خوب درست می‌شه.","نه سردم، فقط انتخابی گرمم.","برای خودم زندگی می‌کنم، نه ویترین.","همیشه آنلاین نیستم، ولی هستم.","بی‌حاشیه؛ باحال‌تر از چیزی که فکر می‌کنی.","دلم آرامش می‌خواد، نه شلوغی.","بعضی حرف‌ها رو فقط به خودم می‌زنم.","قرار نیست همه منو بفهمن.","کم حرف می‌زنم، زیاد می‌بینم.","خنده‌م واقعی‌تر از ظاهرم جدیه.","از آدم‌های ساده با ذهن شلوغ.","همیشه یه آهنگ برای هر حالم دارم.","نه کامل، نه مصنوعی.","به وقتش می‌خندم، به وقتش می‌رم.","از دور آروم، از نزدیک داستان.","بعضی چیزها رو فقط زمان حل می‌کنه.","با خودم رفیقم، همین کافیه.","هر روز یه دلیل تازه برای ادامه.","نه عجله دارم، نه عقبم.","یه گوشه دنج، یه پلی‌لیست خوب.","شاید ساکتم، ولی بی‌تفاوت نیستم.","از چیزهای کوچیک خوشحال می‌شم.","دنبال آدم‌های واقعی‌ام.","حرف کم، حس زیاد.","خودم رو با دیروز خودم مقایسه می‌کنم.","آدمِ شب‌های فکر کردن.","وقتی لازم باشه، خیلی محکمم.","علاقه‌مند به آرامش‌های بی‌دلیل.","یه لبخند دارم برای روزهای سخت.","همه‌چیز رو لازم نیست گفت.","با احترام نزدیک می‌شم، با بی‌احترامی دور.","زندگی رو با فیلتر نمی‌بینم.","کم توقع، پرحس.","به جای توضیح، رفتار می‌کنم.","مودم با چای و آهنگ آروم بهتره.","قرار نیست شبیه کسی باشم.","از شروع‌های تازه خوشم میاد.","گاهی دور شدن، بهترین جوابه.","خوب بودنم همیشه پر سر و صدا نیست.","یه آدم با کلی ایده نصفه‌شب.","برای چیزهای واقعی وقت می‌ذارم.","نه بی‌نقص، فقط صادق.","منو از انتخاب‌هام بشناس.","با هر چیزی که ارزشش رو داشته باشه می‌مونم.","آدمِ لحظه‌های ساده‌ام.","از قضاوت زودهنگام خوشم نمیاد.","کم‌نور، ولی خاموش نه.","گاهی بهترین جواب، هیچ جوابه.","به خودم قول دادم کمتر سخت بگیرم.","از دوری‌های بی‌دلیل عبور کردم.","سلیقه‌م آرامش و آدم‌های بافکره.","یه قلب حساس پشت یه ظاهر معمولی.","هر کسی به اندازه رفتارش نزدیکه.","نه گم شدم، نه پیدا؛ در حال ساختنم.","با سکوت هم می‌شه حرف زد.","روزهای خوب رو خودم می‌سازم.","از خاطره‌های خوب انرژی می‌گیرم.","دنبال حس خوبم، نه شلوغی.","کم‌حرفی همیشه نشونه خالی بودن نیست.","با آدم درست، خیلی حرف دارم.","بهترین نسخه‌م هنوز در راهه.","یه ذهن شلوغ با قلبی آروم.","ساده دوست دارم، سخت فراموش می‌کنم.","از نقش بازی کردن خسته‌ام.","به وقتش خیلی خنده‌دارم.","بیشتر از چیزی که نشون می‌دم اهمیت می‌دم.","زندگی کوتاه‌تر از اونیه که خودت نباشی.","همیشه یه راه برای بهتر شدن هست.","با موزیک، دنیا قابل‌تحمل‌تره.","نه خاصم، نه معمولی؛ خودمم.","بعضی آدم‌ها حس خونه می‌دن.","از حالم بپرس، نه از آخرین بازدیدم.","هر چیزی رو همه‌جا نمی‌گم.","خوشبختی برای من یعنی ذهن آروم.","از چیزهای واقعی جا نمی‌مونم.","یه آدم با امیدهای کوچیک و جدی.","آرامش، لوکس‌ترین حس دنیاست.","یه آدم ساده با رویاهای جدی.",
]

_used = {}


def get_biography(chat_id=None):
    key = chat_id if chat_id is not None else "__default__"
    used = _used.setdefault(key, set())
    available = [index for index in range(len(BIOGRAPHIES)) if index not in used]
    if not available:
        used.clear()
        available = list(range(len(BIOGRAPHIES)))
    index = random.SystemRandom().choice(available)
    used.add(index)
    return BIOGRAPHIES[index]
